<td data-label="Trạng thái"><span class="status <?= $product['status']==='active'?'confirmed':'cancelled' ?>"><i></i><?= $product['status']==='active'?'Đang sử dụng':'Ngừng sử dụng' ?></span></td><td data-label="Thao tác"><div class="account-actions"><button class="button product-details" type="button">Xem</button><?php if ($access['admin']): ?><button class="button edit-product" type="button">Sửa</button><?php endif; ?></div></td></tr><?php endforeach; ?>
